const loadTasks = async () => {
  const tasks = await (await fetch(`/api/projects/${match[1]}/tasks`)).json();
  const filter = document.querySelector('#task-filter').value;
  const visible = tasks.filter(task => filter === 'All' || (filter === 'Completed') === task.completed);
  document.querySelector('#tasks').innerHTML = visible.map(task => `<div class="project-row" data-testid="task-row"><span class="project-name">${escapeHtml(task.title)}</span><label><input type="checkbox" aria-label="Complete ${escapeHtml(task.title)}" data-task-id="${task.id}" ${task.completed ? 'checked' : ''}></label></div>`).join('');
  document.querySelectorAll('#tasks input').forEach(box => box.addEventListener('change', async () => { await fetch(`/api/tasks/${box.dataset.taskId}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: box.checked }) }); loadTasks(); }));
};
document.querySelector('#task-filter').addEventListener('change', loadTasks);
document.querySelector('#task-form').addEventListener('submit', async event => {
  event.preventDefault();
  const title = document.querySelector('#task-title').value.trim();
  if (!title) { document.querySelector('#alert').innerHTML = '<p role="alert">Task title is required</p>'; return; }
  const result = await fetch(`/api/projects/${match[1]}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }) });
  if (!result.ok) { document.querySelector('#alert').innerHTML = '<p role="alert">Task title is required</p>'; return; }
  document.querySelector('#task-title').value = '';
  document.querySelector('#alert').innerHTML = '';
  await loadTasks();
});
await loadTasks();
document.querySelector('#back').addEventListener('click', () => { history.pushState({}, '', '/'); render(); });

